// Package fincrt is the Go runtime support package for code generated by the
// FinCore compilers (finc0/finc1/finc2). See section 8 of the FinCore spec.
//
// Type mapping (FinCore -> Go): usize -> uint, u8/byte -> uint8, u64 -> uint64,
// Duration -> fincrt.Duration (uint64 nanoseconds), Signal -> fincrt.Signal (uint8).
//
// Name mapping for builtins and stdlib (FinCore -> Go):
//
//	copy(dst, src)            -> fincrt.Copy(dst, src)
//	bytesEqual(a, b)          -> fincrt.BytesEqual(a, b)
//	strBytes(s)               -> fincrt.StrBytes(s)
//	bytesToStr(b)             -> fincrt.BytesToStr(b)
//	formatUint(v, dst)        -> fincrt.FormatUint(v, dst)
//	parseUint(src)            -> fincrt.ParseUint(src)
//	NewContext()              -> fincrt.NewContext()
//	NewScope(n)               -> fincrt.NewScope(n)   (returns *fincrt.Scope)
//	conns.AcquireSlot(ctx, &pool) -> fincrt.AcquireSlot(conns, ctx, pool[:])
//	conns.ReleaseSlot(slot)   -> fincrt.ReleaseSlot(conns, slot)
//	conns.Go(slot, fn)        -> fincrt.Go(conns, slot, fn)
//	conns.WaitTimeout(d) / conns.Wait() -> same methods on *fincrt.Scope
//	ErrEOF, ErrTimeout, ...   -> fincrt.ErrEOF, fincrt.ErrTimeout, ...
//	Second, Millisecond, ...  -> fincrt.Second, fincrt.Millisecond, ...
//	SIGINT, SIGTERM           -> fincrt.SIGINT, fincrt.SIGTERM
//	Context, Conn, Listener, Net, Signals, Scope, Slot, FS, Env, Stdio, Exec,
//	ExitStatus, CancelFunc    -> fincrt.<same name>
//
// Capabilities injected by the generated Go main(): fincrt.DefaultNet(),
// fincrt.DefaultSignals(), fincrt.DefaultClock(), fincrt.DefaultFS(),
// fincrt.DefaultEnv(), fincrt.DefaultStdio(), fincrt.DefaultExec().
// Clock (no methods in v0.1) maps to fincrt.Clock.
package fincrt
